mapper.select:
INSERT INTO t_comment_like (user_id, comment_id, create_time) SELECT source.user_id, source.comment_id, source.create_time FROM (VALUES
(#{item.userId}, #{item.commentId}, #{item.createTime})
) AS source(user_id, comment_id, create_time) JOIN t_comment comment ON comment.id = source.comment_id ON CONFLICT (user_id, comment_id) DO NOTHING RETURNING user_id, comment_id
